<?php $tabs = ['journals' => 'adm.t_journals', 'site' => 'adm.t_site', 'system' => 'adm.t_system', 'tools' => 'adm.t_tools', 'outbox' => 'adm.t_outbox']; $er = fn($k) => ''; ?>
<div class="be_page"><div class="be_pagehead"><h1><?= e(t('menu.admin')) ?></h1></div>
<ul class="be_tabs"><?php foreach ($tabs as $k => $l): ?><li class="<?= $k === $tab ? 'active' : '' ?>"><a href="<?= e(url('admin', 'index', [$k])) ?>"><?= e(t($l)) ?></a></li><?php endforeach; ?></ul><div class="be_card">
<?php if ($tab === 'journals'): ?><?php $rows = []; $n = count($journals); foreach ($journals as $i => $j) $rows[] = ['cells' => ['<a href="' . e(url(null, null, [], [], $j['path'])) . '" target="_blank">' . e($j['name']) . '</a>', '/' . e($j['path']), (int)$j['subs'], e($j['enabled'] ? t('adm.enabled') : t('set.disabled'))], 'actions' => [
  [t('wizard.edit'), url('admin', 'journal', [$j['id']])],
  [t('grid.move_up'), url('admin', 'moveJournal', [$j['id'], 'up']), ['post' => 1, 'class' => 'order_items', 'disabled' => $i === 0]], [t('grid.move_down'), url('admin', 'moveJournal', [$j['id'], 'down']), ['post' => 1, 'class' => 'order_items', 'disabled' => $i === $n - 1]],
  [t('wizard.delete'), url('admin', 'deleteJournal', [$j['id']]), ['post' => 1, 'class' => 'delete', 'confirm' => t('set.confirm_delete')]]]]; ?>
<?= grid(t('adm.t_journals'), [[t('adm.add_journal'), url('admin', 'journal')]], [[t('set.title'), 40], [t('adm.path'), 25], [t('iss.articles'), 15], [t('set.status'), 20]], $rows) ?>
<?php elseif ($tab === 'site'): ?><form class="cmp_form be_form" method="post" action="<?= e(url('admin', 'saveSite')) ?>"><?= csrf_field() ?><div class="fields">
<?= field(t('adm.site_title'), 'title', $site['title'], ['required' => true, 'maxlength' => 255]) ?><?= field(t('adm.intro'), 'intro', $site['intro'], ['type' => 'textarea', 'rows' => 4]) ?>
<?= field(t('adm.redirect'), 'redirect_journal', $site['redirect'], ['type' => 'select', 'options' => array_column($journalPaths, 'path', 'path'), 'required' => true, 'help' => t('adm.redirect_help')]) ?><?= field(t('adm.min_pw'), 'minPasswordLength', $site['minPasswordLength'], ['type' => 'number', 'maxlength' => 2]) ?></div>
<div class="buttons"><button class="submit" type="submit"><?= e(t('wizard.save')) ?></button></div></form>
<?php elseif ($tab === 'system'): ?><table class="be_table"><tbody><?php foreach ($info as $k => $v): ?><tr><th scope="row"><?= e($k) ?></th><td><?= e($v) ?></td></tr><?php endforeach; ?></tbody></table>
<?php elseif ($tab === 'tools'): ?><div class="be_tools"><form method="post" action="<?= e(url('admin', 'clearCache')) ?>"><?= csrf_field() ?><h3><?= e(t('adm.clear_cache')) ?></h3><p class="muted"><?= e(t('adm.clear_cache_help')) ?></p><button class="be_btn" type="submit"><?= e(t('adm.clear_cache')) ?></button></form>
<form method="post" action="<?= e(url('admin', 'expireSessions')) ?>" onsubmit="return confirm('<?= e(t('adm.confirm_sessions')) ?>')"><?= csrf_field() ?><h3><?= e(t('adm.expire_sessions')) ?></h3><p class="muted"><?= e(t('adm.expire_help')) ?></p><button class="be_btn be_btn_danger" type="submit"><?= e(t('adm.expire_sessions')) ?></button></form></div>
<?php else: ?><form class="be_filters" method="get" action="<?= e(url('admin', 'index', ['outbox'])) ?>"><input type="search" name="q" value="<?= e($q) ?>" placeholder="<?= e(t('adm.search_outbox')) ?>"><button class="be_btn" type="submit"><?= e(t('dash.filter')) ?></button></form>
<table class="be_table"><thead><tr><th>#</th><th><?= e(t('wf.to')) ?></th><th><?= e(t('wf.subject')) ?></th><th><?= e(t('wf.sent')) ?></th><th></th></tr></thead><tbody><?php foreach ($rows as $r): ?><tr><td><?= (int)$r['id'] ?></td><td><?= e($r['to_addr']) ?></td><td><?= e($r['subject']) ?></td><td class="muted"><?= e($r['created_at']) ?> <?= $r['sent'] ? '' : '(' . e(t('wf.logged_only')) . ')' ?></td><td><a class="be_btn" href="<?= e(url('admin', 'email', [$r['id']])) ?>"><?= e(t('rev.details')) ?></a></td></tr><?php endforeach; ?>
<?php if (!$rows): ?><tr><td colspan="5" class="muted"><?= e(t('adm.outbox_empty')) ?></td></tr><?php endif; ?></tbody></table><?= paginate($total, $page, $per, fn($n) => url('admin', 'index', ['outbox'], array_filter(['q' => $q, 'page' => $n]))) ?>
<form method="post" action="<?= e(url('admin', 'purgeOutbox')) ?>"><?= csrf_field() ?><button class="be_btn" type="submit"><?= e(t('adm.purge')) ?></button></form><?php endif; ?></div></div>
